arguments.cmd:
mount | grep -i chall; python3 - <<'EOF'
import os
for root, dirs, files in os.walk('/challenge/inhere'):
    for name in dirs + files:
        p = os.path.join(root, name)
        try:
            attrs = os.listxattr(p)
            if attrs:
                print(p, attrs, [os.getxattr(p, a) for a in attrs])
        except OSError as e:
            print('ERR', p, e)
print('xattr scan done')
EOF

